import json,random,collections
meta={json.loads(l)['id']:json.loads(l) for l in open('/workspace/case/dataset/train_curve.meta.jsonl')}
def load(n):
    d=json.load(open(f'runs/{n}.json')); return {e['example_id']:e for e in d['examples']}
R={n:load(n+'-curve') for n in ['r1-03','r2-04','r4-01','r5-02','r6-01','r7-01']}
ids=sorted(R['r4-01'])
fam={i:meta[i]['family'] for i in ids}
def paired(a,b,key='score'):
    d=[R[a][i][key]-R[b][i][key] for i in ids]
    return sum(x>1e-9 for x in d),sum(x<-1e-9 for x in d)
def boot(a,b,B=4000):
    fams=sorted(set(fam.values())); byf=collections.defaultdict(list)
    for i in ids: byf[fam[i]].append(R[a][i]['score']-R[b][i]['score'])
    rnd=random.Random(1); res=[]
    for _ in range(B):
        s=0;n=0
        for f in (rnd.choice(fams) for _ in fams): s+=sum(byf[f]); n+=len(byf[f])
        res.append(s/n)
    res.sort(); return round(res[int(.025*B)],3),round(res[int(.975*B)],3)
for a,b in [('r4-01','r1-03'),('r4-01','r2-04'),('r7-01','r4-01'),('r6-01','r4-01'),('r6-01','r7-01'),('r6-01','r5-02'),('r7-01','r5-02')]:
    m=sum(R[a][i]['score']-R[b][i]['score'] for i in ids)/200
    print(a,'vs',b,'diff',round(m,4),'better/worse',paired(a,b),'CI',boot(a,b))
# top1 agreement and union
top=lambda n,i:json.loads(R[n][i]['answer'])[0]
for a,b in [('r4-01','r7-01'),('r6-01','r7-01'),('r6-01','r4-01'),('r1-03','r4-01')]:
    print(a,b,'top1 agree',sum(top(a,i)==top(b,i) for i in ids)/200,'top3 identical',sum(R[a][i]['answer']==R[b][i]['answer'] for i in ids))
ok=lambda n,i:R[n][i]['statistics']['acc1']==1
print('acc1 both wrong r6/r7/r4', sum(not ok('r6-01',i) and not ok('r7-01',i) and not ok('r4-01',i) for i in ids), 'any right', sum(ok('r6-01',i) or ok('r7-01',i) or ok('r4-01',i) for i in ids))
print('r6 right r7 wrong',sum(ok('r6-01',i) and not ok('r7-01',i) for i in ids),'r7 right r6 wrong',sum(ok('r7-01',i) and not ok('r6-01',i) for i in ids))
# style tables
sty=lambda i:meta[i]['style']
for n in ['r1-03','r4-01','r6-01','r7-01']:
    t=collections.defaultdict(list)
    for i in ids: t[sty(i)].append(R[n][i]['score'])
    print(n,{k:(len(v),round(sum(v)/len(v),3)) for k,v in sorted(t.items())})
# hard tags
E

